#if UNITY_EDITOR
using System;
using System.IO;
using System.Linq;
using System.Reflection;
using System.Security.Cryptography;
using LastRail.Battle;
using Newtonsoft.Json.Linq;
using NUnit.Framework;
namespace LastRail.Tests.EditMode {
 public sealed class CombatBActiveTimingTests {
  const string Root="D:/Project/LASTRAIL/";
  static BCarriageBuffModel Model(int rank=5,bool changedDefinitions=false){
   var json=File.ReadAllText(Root+"QA/CombatBMigration-20261002/BuffConsumer/original-definitions.json");if(changedDefinitions){var defs=JObject.Parse(json);((JArray)defs["definitions"]).Single(d=>(string)d["type"]=="BCB02")["values"][4]=2001;json=defs.ToString();}string hash;
   using(var sha=SHA256.Create())hash=BitConverter.ToString(sha.ComputeHash(System.Text.Encoding.UTF8.GetBytes(json))).Replace("-","").ToLowerInvariant();
   var trace=((JArray)JObject.Parse(File.ReadAllText(Root+"QA/CommanderS1-20260922/combat-b-buff-traces-20261002.json"))["traces"]).Single(t=>(string)t["name"]=="BCB02_R"+rank+"_ACTUAL_DB_CAPTURE_AND_CALCULATION");
   var d=(JObject)trace["response"]["departure"].DeepClone();
   var initial=new JObject{["contextId"]="U13_LOCAL_TIMING_VALIDATION",["mode"]="EXTERIOR",["cars"]=new JArray(((JArray)d["cars"]).Select(c=>new JObject{["slot"]=c["slot"].DeepClone(),["body"]="NORMAL",["actor"]=(string)c["occupant"]["kind"]=="CARGO"?"ABSENT":"UP"}))};
   return new BCarriageBuffModel(new BCarriageBuffDefinitions(json,hash),d,initial);
  }
  static object Call(BasicCombatSimulation s,string name,params object[] args){var m=typeof(BasicCombatSimulation).GetMethod(name);Assert.NotNull(m,"Missing original acceptance timing boundary: "+name);try{return m.Invoke(s,args);}catch(TargetInvocationException e){throw e.InnerException;}}
  static BasicCombatSimulation Fresh(int rank=5,bool auto=false,bool bound=true,long haste=0,long cdr=0,BCarriageBuffModel source=null,long enchant=0){
   // Historical CE03 is only the existing skill/Ready/clock test host; no B skill policy is issued.
   var t=(JObject)JObject.Parse(File.ReadAllText(Root+"Worktrees/11ec/LASTRAIL/attendance-pass-20260907/server/audit-results/ce03-local-producer/draft.json"))["draft"]["template"];
   var actors=((JArray)t["operators"]).Select((o,i)=>new BasicCombatActor((string)o["operatorId"],false,false,false,i,1000,50,0,100000,1,0,BasicCombatTarget.EnemyAny,4000)).Concat(new[]{new BasicCombatActor("train",false,true,false,5,5000,0,0,100000,1,0,BasicCombatTarget.EnemyAny,4000)}).ToArray();
   var enemy=new BasicCombatActor("enemy",true,false,false,0,1000000,0,0,100000,1,0,BasicCombatTarget.Train,4000);
   var s=new BasicCombatSimulation("U13_TEST_ONLY_ORIGINAL_CE03",500000,1,actors,new[]{new[]{enemy}});s.ConfigureSkills(t,"op_eve",50);s.ConfigureLocalOperatorAutomation(auto);
   if(bound)Call(s,"ConfigureLocalActiveTimingForValidation",source??Model(rank),"op_eve",0,new[]{new CombatTimingSource("original-haste",haste)},new[]{new CombatTimingSource("original-cdr",cdr)},enchant==0?null:new CombatTimingSource("original-en08",enchant));
   return s;
  }
  static JObject State(BasicCombatSimulation s)=>JObject.Parse(s.CaptureLocalState());
  static long Ready(BasicCombatSimulation s)=>(long)((JArray)State(s)["skillReady"]).Single(r=>(string)r["key"]=="op_eve/op_eve.active")["ready"];
  static void Steps(BasicCombatSimulation s,int n)=>s.Advance(checked((long)n*500000),n);
  static void Transition(BasicCombatSimulation s,string id,string value,long rev)=>Call(s,"ApplyLocalActiveTimingTransition",new JObject{["eventId"]=id,["expectedRevision"]=rev,["kind"]="BODY",["slot"]=0,["value"]=value});
  [TestCase(1,372)][TestCase(5,335)] public void AcceptedSourceChangesOriginalReadyAndActualReacceptance(int rank,int expected){var s=Fresh(rank);s.RequestSkill("first","op_eve","op_eve.active");Steps(s,1);Assert.AreEqual("CASTING",s.CommandStatus("first"));Assert.AreEqual(expected,Ready(s));Steps(s,expected-2);s.RequestSkill("early","op_eve","op_eve.active");Steps(s,1);Assert.AreEqual("CASTING",s.CommandStatus("early"));Assert.AreEqual(expected+(expected-1),Ready(s));}
  [Test] public void OneTickBeforeReadyRejectsWithoutNewSource(){var s=Fresh();s.RequestSkill("first","op_eve","op_eve.active");Steps(s,1);Steps(s,332);s.RequestSkill("early","op_eve","op_eve.active");Steps(s,1);Assert.AreEqual("REJECTED_COOLDOWN",s.CommandStatus("early"));Assert.AreEqual(335,Ready(s));Assert.AreEqual(1,((JArray)State(s)["localActiveTiming"]["receipts"]).Count);}
  [Test] public void BrokenHasteZeroMatchesUnmodifiedOriginalReady(){var s=Fresh();Transition(s,"break","BROKEN",0);var old=Fresh(bound:false);foreach(var x in new[]{s,old}){x.RequestSkill("first","op_eve","op_eve.active");Steps(x,1);}Assert.AreEqual(401,Ready(s));Assert.AreEqual(Ready(old),Ready(s));}
  [Test] public void SameGroupHasteAndOtherCdrRoundOnceOnActualReady(){var s=Fresh(haste:15000,cdr:2000);s.RequestSkill("first","op_eve","op_eve.active");Steps(s,1);Assert.AreEqual(120,Ready(s));}
  [Test] public void ManualAndAutoUseSameFrozenAcceptance(){var manual=Fresh();var auto=Fresh(auto:true);manual.RequestSkill("manual","op_eve","op_eve.active");Steps(manual,1);Steps(auto,1);Assert.AreEqual(335,Ready(auto));Assert.AreEqual(Ready(manual),Ready(auto));Assert.AreEqual(1,((JArray)State(auto)["localActiveTiming"]["receipts"]).Count);}
  [Test] public void BreakReturnAndBorrowedModelCannotResetRunningReady(){var model=Model();var s=Fresh(source:model);s.RequestSkill("first","op_eve","op_eve.active");Steps(s,1);Transition(s,"break","BROKEN",0);Assert.AreEqual(335,Ready(s));Steps(s,334);s.RequestSkill("broken","op_eve","op_eve.active");Steps(s,1);Assert.AreEqual(736,Ready(s));Transition(s,"return","NORMAL",1);Assert.AreEqual(736,Ready(s));Assert.AreEqual(0,model.Revision);Steps(s,400);s.RequestSkill("returned","op_eve","op_eve.active");Steps(s,1);Assert.AreEqual(1071,Ready(s));}
  [Test] public void PauseSpeedDebtAndSplitAdvanceUseOriginalLogicalClock(){var a=Fresh();var b=Fresh();foreach(var s in new[]{a,b}){s.RequestSkill("first","op_eve","op_eve.active");s.SetPaused(true);var before=s.CaptureLocalState();s.Advance(1234567,2);Assert.AreEqual(before,s.CaptureLocalState());s.SetPaused(false);s.SetSpeed(3);}a.Advance(2000000,2);a.Advance(0,4);for(int i=0;i<4;i++)b.Advance(500000,2);Assert.AreEqual(6,a.Tick);Assert.AreEqual(a.CaptureLocalState(),b.CaptureLocalState());Assert.AreEqual(335,Ready(a));}
  [Test] public void DuplicateIdentityCannotRestartOrRepublish(){var s=Fresh();s.RequestSkill("same","op_eve","op_eve.active");Steps(s,1);var before=s.CaptureLocalState();Assert.AreEqual("CASTING",s.RequestSkill("same","op_eve","op_eve.active"));Assert.Throws<InvalidOperationException>(()=>s.RequestSkill("same","op_eve","op_eve.ultimate"));Assert.AreEqual(before,s.CaptureLocalState());}
  [Test] public void RestoreFrozenSourcesAndReadyWithoutReinterpretingCurrentBody(){var s=Fresh();s.RequestSkill("first","op_eve","op_eve.active");Steps(s,1);Transition(s,"break","BROKEN",0);s.Advance(123456,0);var json=s.CaptureLocalState();var restored=BasicCombatSimulation.RestoreLocalState(json,()=>Fresh());Assert.AreEqual(json,restored.CaptureLocalState());Steps(s,345);Steps(restored,345);Assert.AreEqual(s.CaptureLocalState(),restored.CaptureLocalState());Assert.Throws<ArgumentException>(()=>BasicCombatSimulation.RestoreLocalState(json,()=>Fresh(1)));Assert.Throws<ArgumentException>(()=>BasicCombatSimulation.RestoreLocalState(json,()=>Fresh(bound:false)));}
  [TestCase("ready")][TestCase("source")][TestCase("receipt")] public void RestoreRejectsTamperedTimingAtomically(string field){var s=Fresh();s.RequestSkill("first","op_eve","op_eve.active");Steps(s,1);var j=State(s);if(field=="ready")((JArray)j["skillReady"]).Single(r=>(string)r["key"]=="op_eve/op_eve.active")["ready"]=336;if(field=="source")j["localActiveTiming"]["buffs"]["actions"][0]["source"]["skillHasteBps"]=999;if(field=="receipt")j["localActiveTiming"]["receipts"][0]["ready"]=336;Assert.Throws<ArgumentException>(()=>BasicCombatSimulation.RestoreLocalState(j.ToString(),()=>Fresh()));}
  [Test] public void RestoreRejectsCommandDueThatDisagreesWithAcceptance(){var s=Fresh();s.RequestSkill("first","op_eve","op_eve.active");Steps(s,1);var j=State(s);j["commands"][0]["due"]=1000;Assert.Throws<ArgumentException>(()=>BasicCombatSimulation.RestoreLocalState(j.ToString(),()=>Fresh()));}
  [Test] public void RestoreRejectsUnacceptedReadyChange(){var j=State(Fresh());((JArray)j["skillReady"]).Single(r=>(string)r["key"]=="op_eve/op_eve.active")["ready"]=999;Assert.Throws<ArgumentException>(()=>BasicCombatSimulation.RestoreLocalState(j.ToString(),()=>Fresh()));}
  [Test] public void RestoreCannotSubstituteAnotherDefinitionUnderSameVersion(){var s=Fresh();Assert.Throws<ArgumentException>(()=>BasicCombatSimulation.RestoreLocalState(s.CaptureLocalState(),()=>Fresh(source:Model(changedDefinitions:true))));}
  [Test] public void RestoreCannotRelabelModifierOnlyActionIntoHeal(){var s=Fresh();s.RequestSkill("first","op_eve","op_eve.active");Steps(s,1);var j=State(s);var b=j["localActiveTiming"]["buffs"];b["journal"][0]["input"]["kind"]="HEAL";b["actions"][0]["input"]["kind"]="HEAL";b["actions"][0]["source"]["kind"]="HEAL";Assert.Throws<ArgumentException>(()=>BasicCombatSimulation.RestoreLocalState(j.ToString(),()=>Fresh()));}
  [Test] public void ManualSourceFailureDoesNotPartiallyAccept(){var s=Fresh();Call(s,"ApplyLocalActiveTimingTransition",new JObject{["eventId"]="down",["expectedRevision"]=0,["kind"]="ACTOR",["slot"]=0,["value"]="DOWN"});s.RequestSkill("first","op_eve","op_eve.active");var before=State(s);Assert.Throws<ArgumentException>(()=>Steps(s,1));var after=State(s);Assert.AreEqual("QUEUED",s.CommandStatus("first"));Assert.IsTrue(JToken.DeepEquals(before["commands"],after["commands"]));Assert.IsTrue(JToken.DeepEquals(before["localActiveTiming"],after["localActiveTiming"]));Assert.IsTrue(JToken.DeepEquals(before["skillReady"],after["skillReady"]));Assert.AreEqual(before["sequence"],after["sequence"]);}
  [Test] public void SequenceOverflowDoesNotPartiallyAccept(){var j=State(Fresh());j["sequence"]=long.MaxValue;var s=BasicCombatSimulation.RestoreLocalState(j.ToString(),()=>Fresh());s.RequestSkill("first","op_eve","op_eve.active");var before=State(s);Assert.Throws<OverflowException>(()=>Steps(s,1));var after=State(s);Assert.IsTrue(JToken.DeepEquals(before["commands"],after["commands"]));Assert.IsTrue(JToken.DeepEquals(before["localActiveTiming"],after["localActiveTiming"]));Assert.AreEqual(0,Ready(s));Assert.AreEqual(long.MaxValue,(long)after["sequence"]);}
  [Test] public void AutoSequenceOverflowDoesNotEnqueueOrConsumeSource(){var j=State(Fresh(auto:true));j["operatorAutomation"]["sequence"]=long.MaxValue;var s=BasicCombatSimulation.RestoreLocalState(j.ToString(),()=>Fresh(auto:true));Assert.Throws<OverflowException>(()=>Steps(s,1));Assert.AreEqual(0,((JArray)State(s)["commands"]).Count);Assert.AreEqual(0,((JArray)State(s)["localActiveTiming"]["receipts"]).Count);Assert.AreEqual(long.MaxValue,(long)State(s)["operatorAutomation"]["sequence"]);}
  [Test] public void ExistingTargetRetargetKeepsReadyAndRestoresItsNewDue(){var s=Fresh();s.RequestSkill("first","op_eve","op_eve.active");Steps(s,1);var j=State(s);string target=(string)j["commands"][0]["targets"][0];var dead=((JArray)j["actors"]).Single(a=>(string)a["id"]==target);dead["vitals"]["hp"]=0;dead["downCount"]=1;dead["recoverAt"]=100000;var restored=BasicCombatSimulation.RestoreLocalState(j.ToString(),()=>Fresh());Steps(restored,8);Assert.AreEqual("CASTING",restored.CommandStatus("first"));Assert.AreEqual(335,Ready(restored));Assert.AreEqual(17,(long)State(restored)["commands"][0]["due"]);var saved=restored.CaptureLocalState();var resumed=BasicCombatSimulation.RestoreLocalState(saved,()=>Fresh());Assert.AreEqual(saved,resumed.CaptureLocalState());Steps(resumed,8);Assert.AreEqual("APPLIED",resumed.CommandStatus("first"));Assert.AreEqual(335,Ready(resumed));}
  [Test] public void En08RetainsOriginalGroupAndSingleCeil(){var s=Fresh(haste:15000,cdr:2000,enchant:2300);s.RequestSkill("first","op_eve","op_eve.active");Steps(s,1);Assert.AreEqual(93,Ready(s));}
  [Test] public void BorrowedModelAndTimingArraysCannotChangeOwnedAcceptance(){var s=Fresh(bound:false);var model=Model();var haste=new[]{new CombatTimingSource("h",0)};Call(s,"ConfigureLocalActiveTimingForValidation",model,"op_eve",0,haste,Array.Empty<CombatTimingSource>(),null);haste[0]=new CombatTimingSource("h",15000);model.Transition(new JObject{["eventId"]="foreign",["expectedRevision"]=0,["kind"]="BODY",["slot"]=0,["value"]="BROKEN"});s.RequestSkill("first","op_eve","op_eve.active");Steps(s,1);Assert.AreEqual(335,Ready(s));Assert.AreEqual(1,model.Revision);}
  [Test] public void BusyAndUnsupportedInputsNeverFreezeAnotherSource(){var s=Fresh();Assert.AreEqual("REJECTED_ABILITY",s.RequestSkill("unknown","op_eve","B_NEW_INVENTED"));s.RequestSkill("first","op_eve","op_eve.active");Assert.AreEqual("REJECTED_BUSY",s.RequestSkill("busy","op_eve","op_eve.active"));Steps(s,1);Assert.AreEqual(335,Ready(s));Assert.AreEqual(1,((JArray)State(s)["localActiveTiming"]["receipts"]).Count);}
  [Test] public void AcceptedCasterDeathCancelsWithoutRefundingOrResettingReady(){var s=Fresh();s.RequestSkill("first","op_eve","op_eve.active");Steps(s,1);var allies=(System.Collections.IEnumerable)typeof(BasicCombatSimulation).GetField("allies",BindingFlags.Instance|BindingFlags.NonPublic).GetValue(s);foreach(var actor in allies){var type=actor.GetType();var config=(BasicCombatActor)type.GetField("Config",BindingFlags.Instance|BindingFlags.NonPublic).GetValue(actor);if(config.Id=="op_eve")((CombatVitals)type.GetField("Vitals",BindingFlags.Instance|BindingFlags.NonPublic).GetValue(actor)).Damage(1000,s.Tick,false);}Steps(s,1);Assert.AreEqual("CANCELLED_DOWN",s.CommandStatus("first"));Assert.AreEqual(335,Ready(s));Assert.AreEqual(1,((JArray)State(s)["localActiveTiming"]["receipts"]).Count);var json=s.CaptureLocalState();Assert.AreEqual(json,BasicCombatSimulation.RestoreLocalState(json,()=>Fresh()).CaptureLocalState());}
  [Test] public void AutoSourceFailureDoesNotPublishCommandOrSequence(){var j=State(Fresh(auto:true));foreach(var row in (JArray)j["skillReady"])if((string)row["key"]!="op_eve/op_eve.active")row["ready"]=100000;var s=BasicCombatSimulation.RestoreLocalState(j.ToString(),()=>Fresh(auto:true));Call(s,"ApplyLocalActiveTimingTransition",new JObject{["eventId"]="down",["expectedRevision"]=0,["kind"]="ACTOR",["slot"]=0,["value"]="DOWN"});Assert.Throws<ArgumentException>(()=>Steps(s,1));var after=State(s);Assert.AreEqual(0,((JArray)after["commands"]).Count);Assert.AreEqual(0,(long)after["inputSequence"]);Assert.AreEqual(0,(long)after["sequence"]);Assert.AreEqual(0,(long)after["operatorAutomation"]["sequence"]);Assert.AreEqual(0,((JArray)after["localActiveTiming"]["receipts"]).Count);}
  [Test] public void SourceCapacityFailureLeavesOriginalAcceptanceUnchanged(){var s=Fresh();for(int n=0;n<1024;n++)Transition(s,"capacity"+n,"NORMAL",n);s.RequestSkill("first","op_eve","op_eve.active");var before=State(s);Assert.Throws<ArgumentException>(()=>Steps(s,1));var after=State(s);Assert.IsTrue(JToken.DeepEquals(before["commands"],after["commands"]));Assert.IsTrue(JToken.DeepEquals(before["localActiveTiming"],after["localActiveTiming"]));Assert.AreEqual(0,(long)after["sequence"]);Assert.AreEqual(0,Ready(s));}
 }
}
#endif
